var d = ["<script", ' type="application/ld+json">', "<\/script>"], c = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], f = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>SS Pipe Fittings & Flanges Guide</span></div>'], h = ["<main", ' style="', '"><div style="', '"><span style="', '">Product Guide</span><span style="', '">June 2026 \xB7 9 min read</span><h1 style="', '">SS Pipe Fittings and Flanges \u2014 The Complete Piping System Kit</h1><p style="', `">A pipe alone is just a tube. Fittings change direction, branch lines, reduce size, and terminate runs. Flanges create bolted, demountable connections for valves, equipment, and maintenance access. Together with pipes, they form the complete piping system that carries process fluids in every industrial plant. As India's trusted <strong>SS pipe fittings flanges supplier</strong>, <strong>stainless steel pipe manufacturer</strong>, and <strong>SS pipe supplier in Vadodara</strong>, Creative Metal Industries stocks the full range of fittings and flanges in all standard grades and pressure classes.</p></div><div style="`, '"><h2 style="', '">Types of Pipe Fittings</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Fitting Type</th><th style="', '">Function</th><th style="', '">Standard</th><th style="', '">Sizes</th></tr></thead><tbody>', '</tbody></table></div></div><div style="', '"><h2 style="', '">Types of Flanges</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Flange Type</th><th style="', '">Connection Method</th><th style="', '">Best For</th><th style="', '">Pressure</th></tr></thead><tbody>', '</tbody></table></div></div><div style="', '"><h2 style="', '">Material Grades Available</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Material</th><th style="', '">Fitting Spec</th><th style="', '">Flange Spec</th><th style="', '">Grade</th></tr></thead><tbody>', '</tbody></table></div></div><div style="', '"><h2 style="', '">Pressure Ratings \u2014 ASME B16.5 Flange Classes</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Class</th><th style="', '">Max Pressure at Ambient (bar)</th><th style="', '">Max Pressure at 260\xB0C (bar)</th><th style="', '">Typical Use</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">Values for Group 1.1 materials (CS/SS). Actual ratings vary with material group and temperature \u2014 refer to ASME B16.5 Table 2.</p></div><div style="', '"><h2 style="', '">Applications by Industry</h2><div style="', '">', '</div></div><div style="', '"><h2 style="', '">Why Source Fittings & Flanges from Creative Metal Industries?</h2><ul style="', `"><li><strong>Complete range:</strong> Buttweld fittings (A403/A234), forged fittings (A182, B16.11), flanges (A182/A105, B16.5/B16.47) \u2014 all from one supplier</li><li><strong>All grades:</strong> SS 304/316L, Duplex F51, Super Duplex F53, CS A105/WPB, Alloy F11/F22/F91, Inconel, Monel, Hastelloy</li><li><strong>All classes:</strong> Class 150 through 2500. SCH 5S through XXS for buttweld. 3000#/6000#/9000# for forged</li><li><strong>Matching pipes:</strong> We're a <strong>stainless steel pipe manufacturer</strong> + fittings/flanges stockist = single-source for complete piping spools</li><li><strong>IBR certified:</strong> Fittings and flanges with IBR Form III-C for boiler piping applications</li><li><strong>Ready stock:</strong> Common sizes (1/2" to 12", Class 150-600) dispatch same day from our Vadodara warehouse</li></ul></div><div style="`, '"><h2 style="', '">Frequently Asked Questions</h2><div style="', '">', '</div></div><div style="', '"><h2 style="', '">Need SS Pipe Fittings & Flanges?</h2><p style="', '">All types, all grades, all classes. Ready stock Vadodara. Matching pipes available. Single-source piping supply.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/#contact" style="', '">Send Enquiry \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], u = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 SS Pipe Fittings Flanges Supplier India | Stainless Steel Manufacturer | Vadodara</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], l = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], y = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], S = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
const w = JSON.stringify({ "@context": "https://schema.org", "@type": "Article", headline: "SS Pipe Fittings and Flanges \u2014 The Complete Piping System Kit", author: { "@type": "Organization", name: "Creative Metal Industries" }, publisher: { "@type": "Organization", name: "Creative Metal Industries", logo: { "@type": "ImageObject", url: "https://www.creativemetalind.com/logo_cmi.png" } }, datePublished: "2026-06-17", image: "https://www.creativemetalind.com/img/ss_buttweld_fittings.jpg", url: "https://www.creativemetalind.com/blog/ss-pipe-fittings-flanges-guide" }), A = JSON.stringify({ "@context": "https://schema.org", "@type": "FAQPage", mainEntity: [{ "@type": "Question", name: "What are the most common types of SS pipe fittings?", acceptedAnswer: { "@type": "Answer", text: 'The most common SS buttweld fittings (ASTM A403) are: 90\xB0 elbows (long radius and short radius), 45\xB0 elbows, equal tees, reducing tees, concentric reducers, eccentric reducers, caps, and stub ends. For small-bore (\u2264 2"), socket weld fittings (ASTM A182, ASME B16.11) include 90\xB0 elbows, tees, couplings, unions, and plugs in 3000# and 6000# pressure classes.' } }, { "@type": "Question", name: "What is the difference between a Weld Neck and Slip-On flange?", acceptedAnswer: { "@type": "Answer", text: "A Weld Neck (WN) flange has a long tapered hub that is butt-welded to the pipe \u2014 it provides the strongest, highest-integrity connection for high-pressure and high-temperature service. A Slip-On (SO) flange slides over the pipe and is fillet-welded on both sides \u2014 it is easier to align and cheaper, but rated for lower pressure and not suitable for severe cyclic service or temperatures above 260\xB0C." } }, { "@type": "Question", name: "What pressure classes are available for SS flanges?", acceptedAnswer: { "@type": "Answer", text: 'Per ASME B16.5: Class 150, 300, 600, 900, 1500, and 2500 (covers sizes 1/2" to 24"). Per ASME B16.47 (large bore): Class 75, 150, 300, 400, 600, 900 (covers 26" to 60"). Higher class = thicker flange + more/larger bolts = higher pressure and temperature rating. Class 150 handles ~20 bar at ambient; Class 2500 handles ~430 bar.' } }] });
